import axios from '../../api/axiosInstance';

// Locations — backend LocationController (`/locations`, generated by make:module). REST; 422 = field errors.
// Location = { id, code, name, type: store|warehouse, address, active, created_at, updated_at }
// - getAll({ page, per_page, search, type, active, sort: code|name|type|active|created_at, order }) → { data: [Location], meta: { current_page, per_page, total } }   (location-list | inventory-list | register-use)
// - getById(id) → { data: Location }                    (location-list | location-edit)
// - create({ code, name, type, address, active }) → 201 { data }  (location-create; code is upper-cased)
// - update(id, same) → { data }                          (location-edit)
// - remove(id) → { message }                             (location-delete; 422 if it has stock history → deactivate)
const locationApi = {
  getAll:  (params)      => axios.get('/locations', { params }),
  getById: (id)          => axios.get(`/locations/${id}`),
  create:  (payload)     => axios.post('/locations', payload),
  update:  (id, payload) => axios.put(`/locations/${id}`, payload),
  remove:  (id)          => axios.delete(`/locations/${id}`),
};

export default locationApi;
